// Validate hash is in [0, 1] range
if (hash < 0.0f || hash > 1.0f) {
    LOG(ERROR) << "Hash value must be in [0, 1] range, got: " << hash;
    return nullptr;
}

// Use upper_bound to find the first partition point greater than hash
auto it = partition_to_bucket.upper_bound(hash);

// If hash exceeds all partitions, wrap to first bucket
if (it == partition_to_bucket.end()) {
    it = partition_to_bucket.begin();
}

// Return the bucket for this partition point
return it->second;

